dataKeys.postFuncBody:
const d = new Date(value);

if (isNaN(d.getTime())) {
    return "N/A";
}

const pad = n => String(n).padStart(2, "0");
const dt = d.toLocaleDateString(undefined, {
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
});
// return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ` +
//       `${pad(d.getHours())}:${pad(d.getMinutes())}`;
return `${dt} ` + `${pad(d.getHours())}:${pad(d.getMinutes())}`;

settings.cardCss:
.card {
   width: 100%;
   height: 100%;
   border: 2px solid #ccc;
   border-radius: 8px;
   box-sizing: border-box;
   background: #fff;
   color: #263238;
   overflow: hidden;
}

.card .content {
   padding: 20px;
   display: flex;
   flex-direction: column;
   align-items: stretch;
   justify-content: flex-start;
   gap: 20px;
   width: 100%;
   height: 100%;
   box-sizing: border-box;
   overflow-y: auto;
}

/* Header */

.card .header {
   display: flex;
   align-items: stretch;
   gap: 12px;
   flex-shrink: 0;
}

.card .title-marker {
   width: 5px;
   min-height: 58px;
   border-radius: 3px;
   background: #1976d2;
}

.card .title-group {
   display: flex;
   flex-direction: column;
   justify-content: center;
}

.card h1 {
   margin: 0;
   padding: 0;
   color: #455a64;
   font-size: 24px;
   font-weight: 700;
   line-height: 30px;
   text-transform: uppercase;
   letter-spacing: 0.02em;
}

.card .subtitle {
   margin-top: 3px;
   color: #78909c;
   font-size: 14px;
   font-weight: 400;
   line-height: 20px;
}

/* Main content */

.card .sections {
   display: flex;
   flex-direction: column;
   gap: 20px;
   width: 100%;
}

.card .section {
   width: 100%;
}

.card h2 {
   margin: 0 0 12px;
   padding: 0 0 7px;
   border-bottom: 1px solid #e0e0e0;
   color: #607d8b;
   font-size: 13px;
   font-weight: 700;
   line-height: 18px;
   text-transform: uppercase;
   letter-spacing: 0.06em;
}

/* Status boxes */

.card .status-grid {
   display: grid;
   grid-template-columns: repeat(3, minmax(0, 1fr));
   gap: 12px;
}

.card .info-box {
   min-width: 0;
   padding: 14px;
   border: 1px solid #e2e7ea;
   border-radius: 7px;
   box-sizing: border-box;
   background: #f7f9fa;
}

.card .label {
   display: block;
   margin-bottom: 5px;
   color: #78909c;
   font-size: 12px;
   font-weight: 600;
   line-height: 16px;
}

.card .value {
   color: #263238;
   font-size: 22px;
   font-weight: 500;
   line-height: 28px;
   overflow-wrap: anywhere;
}

.card .value-small {
   font-size: 15px;
   line-height: 22px;
}

/* Identifier rows */

.card .identifier-row {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 20px;
   margin-bottom: 9px;
   padding: 11px 14px;
   border: 1px solid #e2e7ea;
   border-radius: 7px;
   box-sizing: border-box;
   background: #f7f9fa;
}

.card .identifier-row:last-child {
   margin-bottom: 0;
}

.card .identifier-row .label {
   margin: 0;
   flex-shrink: 0;
}

.card .identifier-value {
   min-width: 0;
   color: #263238;
   font-size: 14px;
   font-weight: 600;
   text-align: right;
   overflow-wrap: anywhere;
}

.card .monospace {
   padding: 3px 7px;
   border-radius: 4px;
   background: #e8edef;
   font-family: monospace;
   font-size: 13px;
   letter-spacing: 0.03em;
}

/* Responsive layout */

@media (max-width: 650px) {
   .card .content {
      padding: 16px;
   }

   .card .status-grid {
      grid-template-columns: 1fr;
   }

   .card .identifier-row {
      align-items: flex-start;
      flex-direction: column;
      gap: 4px;
   }

   .card .identifier-value {
      text-align: left;
   }
}

.card {
    width: 100%;
    height: 100%;
    border: 1px solid #e5e7eb;
    border-radius: 10px;
    box-sizing: border-box;
    background: #f0f6ff;

    font-family:
        -apple-system,
        BlinkMacSystemFont,
        "Segoe UI",
        Roboto,
        Inter,
        Arial,
        sans-serif;

    color: #1f2937;
    line-height: 1.55;
    overflow: auto;
}

.card .content {
    width: 100%;
    min-height: 100%;
    padding: 14px 16px;

    display: flex;
    flex-direction: row;
    align-items: flex-start;
    justify-content: flex-start;

    box-sizing: border-box;
}

.card .content .column {
    width: 100%;
    min-width: 0;

    display: flex;
    flex-direction: column;
    justify-content: flex-start;
}

/* Title */
.card h1 {
    position: relative;

    margin: 0 0 8px 0;
    padding: 2px 0 3px 14px;

    font-size: 20px;
    font-weight: 700;
    line-height: 1.25;
    text-transform: none;
    color: #0f172a;
}

.card h1::before {
    content: "";

    position: absolute;
    top: -2px;
    bottom: -2px;
    left: 0;

    width: 4px;

    background: #1f6feb;
    border-radius: 2px;
}
