/* Abstract */
.card .abstract {
    margin: 0 0 10px 0;

    font-size: 14.5px;
    font-weight: 500;
    line-height: 1.5;
    color: #334155;
}

/* Description container */
.card .description {
    margin: 0;

    font-size: 13.5px;
    line-height: 1.55;
    font-weight: 400;
    color: #1f2937;
}

/* Paragraphs contained in the description attribute */
.card .description p {
    margin: 0 0 8px 0;
}

.card .description p:last-child {
    margin-bottom: 0;
}

/* Emphasised text in entity attributes */
.card .abstract strong,
.card .description strong {
    font-weight: 700;
}

